create table wksp_dtesc.sgt_tarea (
    id              number generated by default on null as identity minvalue 1 maxvalue 9999999999999999999999999999 increment by 1 cache
    20 noorder nocycle nokeep noscale not null enable,
    evento_id       number,
    entidad         number not null enable,
    pk_id           number not null enable,
    tipo_tarea_id   number not null enable,
    descripcion     varchar2(1000 byte) not null enable,
    estado          varchar2(20 byte),
    creado_por      varchar2(255 byte),
    creado_el       timestamp(6) default systimestamp,
    actualizado_por varchar2(255 byte),
    actualizado_el  timestamp(6)
);

alter table wksp_dtesc.sgt_tarea
    add constraint chk_sgt_tarea_estado
        check ( estado in ( 'PENDIENTE', 'REALIZADO', 'RECHAZADO' ) ) enable;

alter table wksp_dtesc.sgt_tarea
    add constraint pk_sgt_tarea primary key ( id )
        using index enable;


